import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'cashflow-store',
  description:
    "Read and update the cash plan (cashflow.json): the bank balance, the money the business expects in and out, and what-if scenarios. action:'status' for the 13-week forecast and its warning week; 'set_balance' for the cash in the bank (and the cushion to keep); 'add' to save an expected invoice or bill (an existing name is updated, never duplicated); 'settle' when one arrived or was paid; 'remove' to take one out of the plan; 'what_if' to try a scenario without changing the plan; 'list' for every item.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'set_balance', 'add', 'settle', 'remove', 'what_if', or 'list'.",
      required: true,
    },
    item: {
      type: 'string',
      description: "An expected item's id (e.g. 'cf-3') or name, for settle, remove, and a what-if delay or drop.",
    },
    name: { type: 'string', description: "An item's name, e.g. 'Hollis Bakery invoice' or 'Payroll'." },
    direction: { type: 'string', description: 'in for money coming in, out for a bill or cost.' },
    amount: {
      type: 'number',
      description: 'Amount in ordinary units, e.g. 9600. For set_balance it may be 0 or negative.',
    },
    date: {
      type: 'string',
      description: 'YYYY-MM-DD: when it is expected (the first date, for a repeat); for set_balance, the day of the balance; for settle, the day it happened (default today).',
    },
    recurs: { type: 'string', description: 'none, weekly, biweekly, monthly, quarterly.' },
    until: { type: 'string', description: 'The last date a repeat runs, YYYY-MM-DD.' },
    cushion: { type: 'number', description: 'Cash to keep on hand, in ordinary units, e.g. 12000.' },
    scenario: { type: 'string', description: "A what-if's name, e.g. 'Hire an apprentice'." },
    change: { type: 'string', description: 'For what_if: delay, drop, add, or clear.' },
    weeks: { type: 'number', description: 'For a what-if delay: how many weeks later (a month late is 4).' },
    note: { type: 'string', description: 'A short note, with any reference number exactly as written.' },
  },
  outputs: {
    balance: { type: 'number', description: 'Cash in the bank, in ordinary units like amount.' },
    lowestBalance: { type: 'number', description: 'The lowest week-end balance in the forecast, in ordinary units.' },
    lowWeek: { type: 'string', description: 'The Monday of the tightest week, YYYY-MM-DD.' },
    belowCushion: { type: 'number', description: 'Weeks that end below the cushion.' },
    endBalance: { type: 'number', description: 'The balance after 13 weeks, in ordinary units.' },
    summary: { type: 'string', description: 'What changed, then the forecast; or the listing.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── cashflow-rules-start ──
// Pure derivations shared by the script, the page and the sample conversation:
// integer-cent money, repeat dates, and the 13-week forecast with its tightest
// week, for the plan and for each what-if. Kept self-contained between these
// sentinels so unit tests execute the shipped bytes.
var DAY_MS = 86400000;
var WEEKS = 13;
var RECURS = ['none', 'weekly', 'biweekly', 'monthly', 'quarterly'];
var RECURS_TEXT = { none: 'once', weekly: 'every week', biweekly: 'every two weeks', monthly: 'every month', quarterly: 'every quarter' };
var SHORT_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
function localDay(ms) {
  var d = new Date(ms);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
}
function normalizeDate(text) {
  var raw = String(text || '').trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
  var parsed = Date.parse(raw);
  return isFinite(parsed) ? localDay(parsed) : null;
}
// Local noon, so adding days never trips over a daylight-saving change.
function dayMs(day) {
  return Date.parse(String(day).slice(0, 10) + 'T12:00:00');
}
function addDays(day, n) {
  var d = new Date(dayMs(day));
  d.setDate(d.getDate() + n);
  return localDay(d.getTime());
}
// The same day of the month `months` later; the 31st lands on a shorter month's last day.
function addMonths(day, months, dom) {
  var d = new Date(dayMs(day));
  var date = dom || d.getDate();
  d.setDate(1);
  d.setMonth(d.getMonth() + months);
  d.setDate(Math.min(date, new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate()));
  return localDay(d.getTime());
}
// The k-th date of a series counted from its anchor, so a monthly 31st never drifts.
function occurrence(anchor, recurs, k, dom) {
  if (recurs === 'weekly') return addDays(anchor, 7 * k);
  if (recurs === 'biweekly') return addDays(anchor, 14 * k);
  if (recurs === 'monthly') return addMonths(anchor, k, dom);
  if (recurs === 'quarterly') return addMonths(anchor, 3 * k, dom);
  return k === 0 ? anchor : null;
}
function daysBetween(from, to) {
  return Math.round((dayMs(to) - dayMs(from)) / DAY_MS);
}
function mondayOf(day) {
  return addDays(day, -((new Date(dayMs(day)).getDay() + 6) % 7));
}
function weekLabel(day) {
  return SHORT_MONTHS[Number(day.slice(5, 7)) - 1] + ' ' + Number(day.slice(8, 10));
}
// Integer cents from 9600, '9,600.00' or '-1240', with no float arithmetic.
function parseCents(value) {
  var text = typeof value === 'number' ? (isFinite(value) ? String(value) : '') : String(value == null ? '' : value);
  var m = /^(-?)(\d+)(?:\.(\d*))?$/.exec(text.replace(/[$,\s]/g, ''));
  if (!m) return null;
  var frac = (m[3] || '') + '000';
  var cents = Number(m[2]) * 100 + Number(frac.slice(0, 2)) + (Number(frac.charAt(2)) >= 5 ? 1 : 0);
  return m[1] ? -cents : cents;
}
function toCents(value) {
  var cents = parseCents(value);
  return cents !== null && cents > 0 ? cents : null;
}
function money(cents) {
  var abs = Math.abs(Math.round(cents));
  var whole = String(Math.floor(abs / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return (cents < 0 ? '-' : '') + whole + '.' + pad(abs % 100);
}
function normalizeRecurs(text) {
  var raw = String(text || '').trim().toLowerCase();
  if (RECURS.indexOf(raw) >= 0) return raw;
  if (/two weeks|fortnight|bi-?weekly/.test(raw)) return 'biweekly';
  if (/week/.test(raw)) return 'weekly';
  if (/quarter/.test(raw)) return 'quarterly';
  if (/month/.test(raw)) return 'monthly';
  if (/once|one-?off|single/.test(raw)) return 'none';
  return null;
}
function scenarioNames(records) {
  var names = [];
  records.forEach(function (r) {
    var s = r.status === 'whatif' && r.fields && r.fields.scenario;
    if (s && names.indexOf(s) < 0) names.push(s);
  });
  return names;
}
// The plan's expected items, or the plan with one what-if's changes applied.
function planItems(records, scenario) {
  var changes = records.filter(function (r) {
    return scenario && r.status === 'whatif' && r.fields.scenario === scenario && r.fields.change !== 'add';
  });
  return records
    .filter(function (r) {
      return r.status === 'expected' || (scenario && r.status === 'whatif' && r.fields.scenario === scenario && r.fields.change === 'add');
    })
    .map(function (r) {
      var shift = 0;
      var dropped = false;
      changes.forEach(function (c) {
        if (c.fields.itemId !== r.id) return;
        if (c.fields.change === 'drop') dropped = true;
        if (c.fields.change === 'delay') shift += Math.round(Number(c.fields.weeks) || 0);
      });
      var f = r.fields;
      return dropped
        ? null
        : { id: r.id, name: f.name, direction: f.direction, amountCents: f.amountCents, date: f.date, recurs: f.recurs || 'none', until: f.until || '', dom: f.dom, shiftDays: 7 * shift, whatIf: r.status === 'whatif' };
    })
    .filter(Boolean);
}
// Thirteen weeks from this Monday. A repeat dated before the balance is already in it; a one-off
// that never came stays expected and is counted (and flagged late) in the first week.
function forecast(file, scenario, nowMs) {
  var today = localDay(nowMs);
  var balance = file && file.balance && typeof file.balance.amountCents === 'number' ? file.balance : null;
  var asOf = balance && balance.asOf ? balance.asOf : today;
  var start = mondayOf(today);
  var end = addDays(start, 7 * WEEKS - 1);
  var from = asOf < start ? asOf : start;
  var weeks = [];
  for (var w = 0; w < WEEKS; w++) weeks.push({ start: addDays(start, 7 * w), inCents: 0, outCents: 0, items: [] });
  var late = [];
  planItems((file && file.records) || [], scenario).forEach(function (item) {
    if (!item.date || !(item.amountCents > 0)) return;
    var k = 0;
    if (item.recurs !== 'none') {
      var gap = daysBetween(item.date, from) - item.shiftDays;
      var period = { weekly: 7, biweekly: 14, monthly: 31, quarterly: 92 }[item.recurs] || 7;
      if (gap > 0) k = Math.max(0, Math.floor(gap / period) - 1);
    }
    for (var guard = 0; guard < 600; guard++, k++) {
      var raw = occurrence(item.date, item.recurs, k, item.dom);
      if (!raw || (item.until && raw > item.until)) break;
      var day = item.shiftDays ? addDays(raw, item.shiftDays) : raw;
      if (day > end) break;
      if (item.recurs !== 'none' && day < asOf) continue;
      var isLate = item.recurs === 'none' && day < today;
      var hit = { id: item.id, name: item.name, direction: item.direction, amountCents: item.amountCents, day: day, late: isLate, whatIf: item.whatIf };
      var week = weeks[day < start ? 0 : Math.floor(daysBetween(start, day) / 7)];
      if (item.direction === 'in') week.inCents += item.amountCents;
      else week.outCents += item.amountCents;
      week.items.push(hit);
      if (isLate) late.push(hit);
      if (item.recurs === 'none') break;
    }
  });
  var running = balance ? balance.amountCents : 0;
  var totalIn = 0;
  var totalOut = 0;
  weeks.forEach(function (wk) {
    wk.openCents = running;
    running += wk.inCents - wk.outCents;
    wk.closeCents = running;
    totalIn += wk.inCents;
    totalOut += wk.outCents;
  });
  var cushion = file && typeof file.cushionCents === 'number' ? file.cushionCents : 0;
  var lowest = weeks[0];
  weeks.forEach(function (wk) {
    if (wk.closeCents < lowest.closeCents) lowest = wk;
  });
  return {
    today: today, start: start, asOf: asOf, hasBalance: !!balance, balanceCents: balance ? balance.amountCents : 0,
    cushionCents: cushion, weeks: weeks, lowest: lowest, late: late, inCents: totalIn, outCents: totalOut, endCents: running,
    firstLow: weeks.filter(function (wk) { return wk.closeCents < cushion; })[0] || null,
    firstNegative: weeks.filter(function (wk) { return wk.closeCents < 0; })[0] || null,
    belowCushion: weeks.filter(function (wk) { return wk.closeCents < cushion; }).length,
  };
}
function biggest(week) {
  return week.items
    .filter(function (i) { return i.direction === 'out'; })
    .sort(function (a, b) { return b.amountCents - a.amountCents; })
    .slice(0, 3)
    .map(function (i) { return i.name + ' ' + money(i.amountCents); })
    .reduce(function (text, part, i, all) { return text + (i === 0 ? '' : i === all.length - 1 ? ' and ' : '; ') + part; }, '');
}
// The answer to "when does cash get tight?": the warning week first, with what goes out in it.
function tightLine(f) {
  var low = f.lowest;
  var warn = f.firstNegative || f.firstLow;
  var week = function (w) { return 'the week of ' + weekLabel(w.start) + ' (' + w.start + ')'; };
  var going = function (w) { var out = biggest(w); return out ? ', when ' + out + ' go out' : ''; };
  if (!warn) {
    return 'Cash stays above the ' + money(f.cushionCents) + ' cushion for all ' + WEEKS + ' weeks; the tightest is ' + week(low) + ', ending at ' + money(low.closeCents) + going(low) + '.';
  }
  return (
    (f.firstNegative ? 'Cash runs out in ' : 'Cash first drops below the ' + money(f.cushionCents) + ' cushion in ') + week(warn) +
    ', ending at ' + money(warn.closeCents) + going(warn) + '. ' +
    (low === warn ? 'That is the tightest week.' : 'The tightest is ' + week(low) + ', ending at ' + money(low.closeCents) + '.')
  );
}
function compareLine(name, plan, alt) {
  var low = alt.lowest;
  return (
    name + ': tightest week ' + weekLabel(low.start) + ' at ' + money(low.closeCents) +
    ' (plan: ' + weekLabel(plan.lowest.start) + ' at ' + money(plan.lowest.closeCents) + ')' +
    (alt.firstNegative
      ? '; runs out in the week of ' + weekLabel(alt.firstNegative.start)
      : alt.firstLow
        ? '; below the cushion from the week of ' + weekLabel(alt.firstLow.start)
        : '; never below the cushion') +
    '; ends the 13 weeks at ' + money(alt.endCents) + ' (plan ' + money(plan.endCents) + ')'
  );
}
function itemLine(r, records) {
  var f = r.fields || {};
  if (f.change === 'delay' || f.change === 'drop') {
    var target = records.filter(function (x) { return x.id === f.itemId; })[0];
    var what = target ? target.fields.name + ' (' + target.id + ')' : f.itemId;
    return r.id + ' [what-if ' + f.scenario + '] ' + (f.change === 'drop' ? 'drop ' + what : 'delay ' + what + ' by ' + f.weeks + (Number(f.weeks) === 1 ? ' week' : ' weeks'));
  }
  return (
    r.id + (r.status === 'whatif' ? ' [what-if ' + f.scenario + '] add ' : ' ') + f.name + ': ' + (f.direction === 'in' ? 'in ' : 'out ') +
    money(f.amountCents || 0) + ' ' + (f.recurs && f.recurs !== 'none' ? RECURS_TEXT[f.recurs] + ' from ' + f.date + (f.until ? ' until ' + f.until : '') : 'on ' + f.date) +
    (r.status === 'done' ? ' (done)' : '')
  );
}
function cashPicture(file, nowMs, scenario) {
  var records = (file && file.records) || [];
  var plan = forecast(file, null, nowMs);
  var view = scenario ? forecast(file, scenario, nowMs) : plan;
  var planned = records.filter(function (r) { return r.status === 'expected'; }).length;
  if (!plan.hasBalance && !planned) {
    return { plan: plan, view: view, summary: 'The plan is empty: no bank balance and no expected income or bills yet. Ask for today’s bank balance, the regular bills (payroll, rent, suppliers) and the invoices still to be paid.' };
  }
  var parts = [(scenario ? 'With the what-if ' + scenario + ': ' : '') + tightLine(view)];
  parts.push(
    plan.hasBalance
      ? 'Cash in the bank: ' + money(plan.balanceCents) + ' as of ' + plan.asOf + ' (cushion ' + money(plan.cushionCents) + ').' +
          (daysBetween(plan.asOf, plan.today) > 7 ? ' That balance is ' + daysBetween(plan.asOf, plan.today) + ' days old; a fresh one sharpens the forecast.' : '')
      : 'No bank balance yet, so the forecast starts from zero. Ask for today’s balance.',
  );
  if (view.late.length) {
    parts.push('Late, counted in this week until it arrives or is moved: ' + view.late.map(function (i) { return i.name + ' (' + i.id + ', ' + (i.direction === 'in' ? 'in ' : 'out ') + money(i.amountCents) + ', expected ' + i.day + ')'; }).join('; ') + '.');
  }
  parts.push(
    'Week by week, ending balance: ' +
      view.weeks.map(function (wk) { return weekLabel(wk.start) + ' ' + money(wk.closeCents) + ' (in ' + money(wk.inCents) + ', out ' + money(wk.outCents) + ')'; }).join(' | ') + '.',
  );
  parts.push('Over 13 weeks: in ' + money(view.inCents) + ', out ' + money(view.outCents) + ', ending at ' + money(view.endCents) + '.');
  var names = scenarioNames(records);
  if (names.length) {
    parts.push('What-ifs: ' + names.map(function (n) { return compareLine(n, plan, forecast(file, n, nowMs)); }).join(' | ') + '.');
  }
  return { plan: plan, view: view, summary: parts.join(' ') };
}
// ── cashflow-rules-end ──

const STAGES: [string, ...string[]] = ['expected', 'whatif', 'done', 'removed'];
const plan = rosterStore(gezel.fs, 'cashflow.json', { stages: STAGES, idPrefix: 'cf' });
const now = Date.now();
const today = localDay(now);

type CashRecord = Awaited<ReturnType<typeof plan.list>>[number];

// The balance and cushion sit beside the records in the same file; the roster store keeps them on every write.
async function loadFile(): Promise<Record<string, any>> {
  let raw: string;
  try {
    raw = await gezel.fs.read('cashflow.json');
  } catch {
    return { version: 1, stages: [...STAGES], records: [] };
  }
  return JSON.parse(raw);
}
async function saveTop(patch: Record<string, unknown>): Promise<void> {
  const file = await loadFile();
  Object.assign(file, patch);
  await gezel.fs.write('cashflow.json', JSON.stringify(file, null, 2) + '\n');
}

const GENERIC = ['invoice', 'payment', 'bill', 'from', 'with', 'final'];
function matches(records: CashRecord[], text: string, statuses: string[]): CashRecord[] {
  const wanted = text.trim().toLowerCase();
  const pool = records.filter((r) => statuses.includes(r.status) && (r.status === 'expected' || r.fields.change === 'add'));
  const byId = pool.filter((r) => r.id === wanted);
  if (byId.length) return byId;
  const nameOf = (r: CashRecord) => String(r.fields.name ?? '').toLowerCase();
  const exact = pool.filter((r) => nameOf(r) === wanted);
  if (exact.length) return exact;
  const partial = pool.filter((r) => nameOf(r).includes(wanted) || (!!nameOf(r) && wanted.includes(nameOf(r))));
  if (partial.length) return partial;
  // Fall back to distinctive shared words: 'Hollis invoice' finds 'Hollis Bakery lighting retrofit'.
  const words = (wanted.match(/[a-z]{4,}/g) ?? []).filter((w) => !GENERIC.includes(w));
  let best: CashRecord[] = [];
  let score = 0;
  for (const r of pool) {
    const hits = words.filter((w) => nameOf(r).includes(w)).length;
    if (hits > score) {
      best = [r];
      score = hits;
    } else if (hits && hits === score) best.push(r);
  }
  return best;
}
function resolveOne(records: CashRecord[], text: string, what: string): CashRecord {
  if (!text.trim()) throw new Error("Pass 'item': the id (e.g. 'cf-3') or the name of " + what + ". Call action:'list' to see them.");
  const hits = matches(records, text, ['expected']);
  if (hits.length === 1) return hits[0]!;
  if (!hits.length) throw new Error("Nothing expected in the plan matches '" + text + "'. Call action:'list' to see the items.");
  throw new Error("More than one item matches '" + text + "': " + hits.map((r) => itemLine(r, records)).join(' | ') + '. Pass the id.');
}
function directionOf(text: string | undefined): 'in' | 'out' | null {
  const d = String(text ?? '').trim().toLowerCase();
  if (/^(in|income|incoming|receivable|invoice)$/.test(d)) return 'in';
  if (/^(out|outgoing|expense|bill|cost|payable)$/.test(d)) return 'out';
  return null;
}
function itemFields(isNew: boolean): Record<string, unknown> {
  const fields: Record<string, unknown> = {};
  if (input.direction) {
    const d = directionOf(input.direction);
    if (!d) throw new Error("direction must be 'in' (money coming in) or 'out' (a bill).");
    fields.direction = d;
  }
  if (input.amount !== undefined && input.amount !== null) {
    const cents = toCents(input.amount);
    if (cents === null) throw new Error("amount must be positive, in ordinary units, e.g. 9600.");
    fields.amountCents = cents;
  }
  if (input.date) {
    const d = normalizeDate(input.date);
    if (!d) throw new Error("date must be a date, e.g. '" + today + "'.");
    fields.date = d;
    fields.dom = Number(d.slice(8, 10));
  }
  if (input.recurs) {
    const r = normalizeRecurs(input.recurs);
    if (!r) throw new Error('recurs must be one of: ' + RECURS.join(', ') + '.');
    fields.recurs = r;
  }
  if (input.until) {
    const u = normalizeDate(input.until);
    if (!u) throw new Error('until must be a date, YYYY-MM-DD.');
    fields.until = u;
  }
  if (input.note) fields.note = input.note.trim();
  if (isNew) {
    if (!fields.direction) throw new Error("A new item needs 'direction': in for money coming in, out for a bill.");
    if (!fields.amountCents) throw new Error("A new item needs a positive 'amount', e.g. 9600.");
    if (!fields.date) throw new Error("A new item needs 'date', YYYY-MM-DD (the first date, for a repeat).");
    if (!fields.recurs) fields.recurs = 'none';
  }
  return fields;
}

let note = '';
let focus: string | null = null;

if (input.action === 'set_balance') {
  const cents = parseCents(input.amount);
  if (cents === null) throw new Error("set_balance needs 'amount': the cash in the bank in ordinary units, e.g. 18420.");
  const asOf = input.date ? normalizeDate(input.date) : today;
  if (!asOf) throw new Error("date must be a date, e.g. '" + today + "'.");
  const patch: Record<string, unknown> = { balance: { amountCents: cents, asOf } };
  if (input.cushion !== undefined && input.cushion !== null) {
    const cushion = parseCents(input.cushion);
    if (cushion === null || cushion < 0) throw new Error('cushion must be zero or more, e.g. 12000.');
    patch.cushionCents = cushion;
  }
  await saveTop(patch);
  note = 'Bank balance set to ' + money(cents) + ' as of ' + asOf + (typeof patch.cushionCents === 'number' ? ', with a cushion of ' + money(patch.cushionCents) : '') + '.';
} else if (input.action === 'add') {
  const name = (input.name ?? input.item ?? '').trim();
  if (!name) throw new Error("add needs 'name', e.g. 'Hollis Bakery invoice'.");
  const records = await plan.list();
  const existing = records.find((r) => r.status === 'expected' && String(r.fields.name ?? '').toLowerCase() === name.toLowerCase());
  if (existing) {
    const updated = await plan.update(existing.id, { fields: itemFields(false), note: 'Updated' });
    note = 'Updated ' + itemLine(updated, records) + '.';
  } else {
    const added = await plan.add({ status: 'expected', fields: { name, ...itemFields(true) } });
    note = 'Added ' + itemLine(added, records) + '.';
  }
} else if (input.action === 'settle') {
  const records = await plan.list();
  const rec = resolveOne(records, input.item ?? input.name ?? '', 'the item that came in or was paid');
  const f = rec.fields;
  const cents = input.amount !== undefined && input.amount !== null ? toCents(input.amount) : Number(f.amountCents);
  if (!cents) throw new Error('amount must be positive, in ordinary units.');
  const on = input.date ? normalizeDate(input.date) : today;
  if (!on) throw new Error("date must be a date, e.g. '" + today + "'.");
  const file = await loadFile();
  const asOf = file.balance && typeof file.balance.amountCents === 'number' ? String(file.balance.asOf) : null;
  const recurs = String(f.recurs ?? 'none');
  let after = '';
  if (recurs !== 'none') {
    // The settled one is the first the forecast still counts: on or after the balance date.
    const from = asOf ?? today;
    let k = 0;
    let day = occurrence(String(f.date), recurs, 0, f.dom as number);
    while (day && day < from && k < 1000) day = occurrence(String(f.date), recurs, ++k, f.dom as number);
    const next = occurrence(String(f.date), recurs, k + 1, f.dom as number) as string;
    if (f.until && next > String(f.until)) {
      await plan.transition(rec.id, 'done', { note: 'Last one settled on ' + on });
      after = '; that was the last one';
    } else {
      await plan.update(rec.id, { fields: { date: next, lastSettled: on }, note: 'Settled ' + money(cents) + ' on ' + on });
      after = '; the next one is due ' + next;
    }
  } else {
    await plan.update(rec.id, { fields: { settledOn: on, settledCents: cents } });
    await plan.transition(rec.id, 'done', { note: (f.direction === 'in' ? 'Received ' : 'Paid ') + money(cents) + ' on ' + on });
    after = '; it leaves the forecast';
  }
  let moved = '';
  if (asOf && on >= asOf) {
    const balance = file.balance.amountCents + (f.direction === 'in' ? cents : -cents);
    await saveTop({ balance: { amountCents: balance, asOf } });
    moved = ' Cash in the bank is now ' + money(balance) + '.';
  }
  note = String(f.name) + (f.direction === 'in' ? ' came in: ' : ' was paid: ') + money(cents) + ' on ' + on + after + '.' + moved;
} else if (input.action === 'remove') {
  const records = await plan.list();
  const rec = resolveOne(records, input.item ?? input.name ?? '', 'the item to take out');
  await plan.transition(rec.id, 'removed', { note: input.note ?? 'Taken out of the plan' });
  note = 'Took ' + String(rec.fields.name) + ' (' + rec.id + ') out of the plan.';
} else if (input.action === 'what_if') {
  const records = await plan.list();
  const raw = (input.scenario ?? '').trim();
  if (!raw) throw new Error("what_if needs 'scenario': a short name, e.g. 'Hire an apprentice'.");
  const scenario = scenarioNames(records).find((n) => n.toLowerCase() === raw.toLowerCase()) ?? raw;
  const change = String(input.change ?? '').trim().toLowerCase();
  if (change === 'delay' || change === 'drop') {
    const text = input.item ?? input.name ?? '';
    const targets = text.trim() ? matches(records, text, ['expected']) : [];
    if (!targets.length) throw new Error("A what-if " + change + " needs 'item': the id or name of something expected. Call action:'list' to see them.");
    const weeks = Math.round(Number(input.weeks));
    if (change === 'delay' && (!isFinite(weeks) || weeks === 0)) throw new Error("A delay needs 'weeks', e.g. 4 for a month late.");
    for (const t of targets) {
      const existing = records.find((r) => r.status === 'whatif' && r.fields.scenario === scenario && r.fields.change === change && r.fields.itemId === t.id);
      if (existing) await plan.update(existing.id, { fields: change === 'delay' ? { weeks } : {} });
      else await plan.add({ status: 'whatif', fields: { scenario, change, itemId: t.id, ...(change === 'delay' ? { weeks } : {}) } });
    }
    note = 'What-if ' + scenario + ': ' + change + ' ' + targets.map((t) => String(t.fields.name) + ' (' + t.id + ')').join(' and ') +
      (change === 'delay' ? ' by ' + weeks + (weeks === 1 ? ' week' : ' weeks') : '') + '. The plan itself is unchanged.';
  } else if (change === 'add') {
    const name = (input.name ?? '').trim();
    if (!name) throw new Error("A what-if add needs 'name', e.g. 'Apprentice wages'.");
    const existing = records.find((r) => r.status === 'whatif' && r.fields.scenario === scenario && r.fields.change === 'add' && String(r.fields.name).toLowerCase() === name.toLowerCase());
    if (existing) await plan.update(existing.id, { fields: itemFields(false) });
    else await plan.add({ status: 'whatif', fields: { scenario, change: 'add', name, ...itemFields(true) } });
    note = 'What-if ' + scenario + ': add ' + name + '. The plan itself is unchanged.';
  } else if (change === 'clear') {
    const mine = records.filter((r) => r.status === 'whatif' && r.fields.scenario === scenario);
    if (!mine.length) throw new Error("No what-if is named '" + raw + "'. What-ifs: " + (scenarioNames(records).join(', ') || 'none') + '.');
    for (const r of mine) await plan.transition(r.id, 'removed', { note: 'What-if cleared' });
    note = 'Cleared the what-if ' + scenario + '.';
  } else {
    throw new Error("what_if needs 'change': delay, drop, add, or clear.");
  }
  if (change !== 'clear') focus = scenario;
} else if (input.action === 'status') {
  if (input.scenario) {
    const names = scenarioNames(await plan.list());
    focus = names.find((n) => n.toLowerCase() === input.scenario!.trim().toLowerCase()) ?? null;
    if (!focus) note = "No what-if is named '" + input.scenario + "'; showing the plan. What-ifs: " + (names.join(', ') || 'none') + '.';
  }
} else if (input.action !== 'list') {
  throw new Error("Unknown action '" + input.action + "'. Use status, set_balance, add, settle, remove, what_if, or list.");
}

const file = await loadFile();
const view = cashPicture(file, now, focus);
const records = (file.records ?? []) as CashRecord[];
const listing =
  input.action === 'list'
    ? (file.balance ? 'Cash in the bank: ' + money(file.balance.amountCents) + ' as of ' + file.balance.asOf + '. Cushion: ' + money(file.cushionCents ?? 0) + '.\n' : 'No bank balance yet.\n') +
      (records.filter((r) => r.status === 'expected' || r.status === 'whatif').map((r) => itemLine(r, records)).join('\n') || 'Nothing is expected yet.')
    : '';

gezel.output({
  balance: view.plan.balanceCents / 100,
  lowestBalance: view.view.lowest.closeCents / 100,
  lowWeek: view.view.lowest.start,
  belowCushion: view.view.belowCushion,
  endBalance: view.view.endCents / 100,
  summary: listing || (note ? note + ' ' : '') + view.summary,
});

